import Foundation

/// 3D body figure for the 3D body map (#225): a sculpted body (capsules and ellipsoids fitted to the 2D body map outline,
/// generated by ios/Tools/bodymap/generate3d.py into `Resources/body-<figure>.bm3d`). Our own geometry, no third-party
/// model. Triangles facing the viewer of the front view form the front surface and show the front sheet; the rest form
/// the back surface and show the back sheet, so colours and taps come from the same polygons as the 2D map.
///
/// Model space: x = design x − 100 (figure's right side at −x), y = 410 − design y (feet at 0, up), z toward the viewer
/// of the front view. Texture coordinates: (0, 0) = top-left of the sheet, as drawn by the 2D map.
public struct BodyMesh: Sendable {
    public struct Surface: Sendable {
        public var positions: [SIMD3<Float>]
        public var normals: [SIMD3<Float>]
        public var uvs: [SIMD2<Float>]
        public var indices: [UInt32]
    }

    public let front: Surface
    public let back: Surface

    // MARK: Hit testing

    /// Muscle under a point on the mesh (model space) on the given surface, using the 2D map's hit test.
    public static func muscle(atModel p: SIMD3<Float>, side: BodyMapLayout.Side, figure: BodyMapLayout.Figure,
                              tolerance: Double = 4) -> Muscle? {
        let (x, y) = designPoint(p, side: side)
        return BodyMapLayout.muscle(at: x, y, side: side, figure: figure, tolerance: tolerance)
    }

    /// Design-space point of a model-space point on a sheet. The back sheet is drawn as seen from behind, so its x runs
    /// the other way.
    public static func designPoint(_ p: SIMD3<Float>, side: BodyMapLayout.Side) -> (Double, Double) {
        let y = BodyMapLayout.height - Double(p.y)
        return side == .front ? (Double(p.x) + BodyMapLayout.width / 2, y) : (BodyMapLayout.width / 2 - Double(p.x), y)
    }

    // MARK: Loading

    private static let lock = NSLock()
    nonisolated(unsafe) private static var cache: [BodyMapLayout.Figure: BodyMesh] = [:]

    /// Cached mesh for a figure (first load decompresses ~2 MB; call off the main thread).
    public static func of(_ figure: BodyMapLayout.Figure) -> BodyMesh {
        lock.lock(); defer { lock.unlock() }
        if let m = cache[figure] { return m }
        let m = load(figure) ?? BodyMesh(front: Surface(positions: [], normals: [], uvs: [], indices: []),
                                         back: Surface(positions: [], normals: [], uvs: [], indices: []))
        cache[figure] = m
        return m
    }

    static func load(_ figure: BodyMapLayout.Figure) -> BodyMesh? {
        guard let url = Bundle.module.url(forResource: "body-\(figure.rawValue)", withExtension: "bm3d"),
              let packed = try? Data(contentsOf: url),
              let data = try? (packed as NSData).decompressed(using: .zlib) as Data
        else { return nil }
        return parse(data)
    }

    /// Raw (decompressed) mesh file → front and back surfaces.
    static func parse(_ data: Data) -> BodyMesh? {
        guard data.count >= 16, data.prefix(4) == Data("BM3D".utf8) else { return nil }
        func u32(_ at: Int) -> Int { Int(data.withUnsafeBytes { $0.loadUnaligned(fromByteOffset: at, as: UInt32.self) }.littleEndian) }
        guard u32(4) == 1 else { return nil }
        let nv = u32(8), nt = u32(12)
        let vStart = 16, iStart = vStart + nv * 16
        guard data.count >= iStart + nt * 12 else { return nil }
        let W = Float(BodyMapLayout.width), H = Float(BodyMapLayout.height)

        var design = [SIMD3<Float>](repeating: .zero, count: nv)
        var normal = [SIMD3<Float>](repeating: .zero, count: nv)
        var tris = [UInt32](repeating: 0, count: nt * 3)
        data.withUnsafeBytes { raw in
            for i in 0..<nv {
                let o = vStart + i * 16
                design[i] = SIMD3(raw.loadUnaligned(fromByteOffset: o, as: Float.self),
                                  raw.loadUnaligned(fromByteOffset: o + 4, as: Float.self),
                                  raw.loadUnaligned(fromByteOffset: o + 8, as: Float.self))
                // Design space has y down; model space has y up.
                normal[i] = SIMD3(Float(raw.load(fromByteOffset: o + 12, as: Int8.self)),
                                  -Float(raw.load(fromByteOffset: o + 13, as: Int8.self)),
                                  Float(raw.load(fromByteOffset: o + 14, as: Int8.self))) / 127
            }
            for k in 0..<(nt * 3) { tris[k] = raw.loadUnaligned(fromByteOffset: iStart + k * 4, as: UInt32.self).littleEndian }
        }
        func model(_ d: SIMD3<Float>) -> SIMD3<Float> { SIMD3(d.x - W / 2, H - d.y, d.z) }

        // Split by facing; each surface gets its own copy of the vertices it uses, with its sheet's texture coordinates.
        func surface(front: Bool) -> Surface {
            var map = [Int32](repeating: -1, count: nv)
            var s = Surface(positions: [], normals: [], uvs: [], indices: [])
            s.indices.reserveCapacity(nt * 2)
            for t in 0..<nt {
                let a = Int(tris[t * 3])
                var b = Int(tris[t * 3 + 1]), c = Int(tris[t * 3 + 2])
                guard (normal[a].z + normal[b].z + normal[c].z >= 0) == front else { continue }
                // Counter-clockwise seen from outside in model space (agrees with the stored normals).
                let pa = model(design[a]), pb = model(design[b]), pc = model(design[c])
                let n = normal[a] + normal[b] + normal[c]
                if dot(cross(pb - pa, pc - pa), n) < 0 { swap(&b, &c) }
                for v in [a, b, c] {
                    if map[v] < 0 {
                        map[v] = Int32(s.positions.count)
                        let d = design[v]
                        s.positions.append(model(d))
                        s.normals.append(normal[v])
                        s.uvs.append(SIMD2(front ? d.x / W : (W - d.x) / W, d.y / H))
                    }
                    s.indices.append(UInt32(map[v]))
                }
            }
            return s
        }
        return BodyMesh(front: surface(front: true), back: surface(front: false))
    }

    private static func cross(_ a: SIMD3<Float>, _ b: SIMD3<Float>) -> SIMD3<Float> {
        SIMD3(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x)
    }

    private static func dot(_ a: SIMD3<Float>, _ b: SIMD3<Float>) -> Float { (a * b).sum() }
}
